package com.resumeanalyzer.util;

import java.util.Map;

/** Static, rule-based study suggestions (not generated by an AI model). */
public final class LearningTopics {
    private LearningTopics() {}

    private static final Map<String, String> SPECIFIC = Map.of(
        "React", "Build a small app with components, props, state, hooks and routing.",
        "Spring Boot", "Create a REST service with controllers, JPA repositories and validation.",
        "REST API", "Learn HTTP methods, status codes and JSON, then design and test a small API with Postman.",
        "Docker", "Containerize a sample app with a Dockerfile and run it with docker compose.",
        "Git", "Practice commits, branches, merging and pull requests on a personal repository.",
        "SQL", "Practice SELECT, JOIN, GROUP BY and subqueries on a sample database.",
        "CI/CD", "Set up a simple pipeline that builds and tests a project on every push.");

    public static String suggest(String skill, String category) {
        String s = SPECIFIC.get(skill);
        if (s != null) return s;
        String c = category == null ? "" : category;
        return switch (c) {
            case "Programming" -> "Practice " + skill + " with small exercises, then build a mini project.";
            case "Frontend" -> "Build a small responsive page or component using " + skill + ".";
            case "Backend" -> "Create a simple backend service using " + skill + ".";
            case "Database" -> "Design a small schema and practice " + skill + " queries.";
            case "Tools" -> "Use " + skill + " in a personal project and learn its core commands.";
            case "Concepts" -> "Review " + skill + " fundamentals and solve practice problems.";
            case "Testing" -> "Write and run a few test cases with " + skill + " on a sample app.";
            case "Cloud/DevOps" -> "Follow a beginner tutorial for " + skill + " and deploy a sample app.";
            case "Data/AI" -> "Work through a beginner " + skill + " tutorial using a public dataset.";
            default -> "Learn the fundamentals of " + skill + " and apply them in a small project.";
        };
    }
}
